// 줄: { w: 말하는 사람, f: 표정(joy/angry/sad/surprise), t: 대사 }
//     { bg: 'story/opening' } 배경 그림 바꾸기, { choice: [[보기, 깃발], ...] } 선택지
//     { give: {gold, moon, item, unlock, exp, lise, flag} } 보상
//     hero 줄의 by: { mage, paladin, rogue, ranger, hexblade } 직업별 대사 (없으면 t = 하르반 대사)
//     skipFor: ['paladin'] 그 직업으로 플레이 중이면 이 줄을 건너뜀
//     asHero: true 그 인물 본인을 플레이 중이면(odelia→paladin, seril→ranger) 주인공이 이 줄을 말함
//     🆕 if: '깃발' / ifNot: '깃발' / ifLise: n (리세 신뢰 n 이상) / ifLiseBelow: n / onlyFor: ['paladin']
// 말하는 사람: hero(지금 직업), lise, tabel, merchant, fortune, orvex, seril, odelia, hunter(달사냥꾼), void(그림자), narr(지문)
